const listarOrdenes = `-- name: ListarOrdenes :many
SELECT id, numero, empresa_id, tipo_id, plantilla_id, ticket_id, prospecto_id, cliente_id, servicio_id, zona_id, cuadrilla_id, bodega_id, direccion, lat, lon, contacto_nombre, contacto_telefono, descripcion, tecnico_id, asignada_en, estado, programada_inicio, programada_fin, en_camino_en, en_sitio_en, finalizada_en, resultado, motivo_falla, motivo, creado_por, idempotencia, version, created_at, updated_at, origen FROM campo.ordenes
WHERE ($1::bigint IS NULL OR id < $1)
  AND ($2::boolean
       OR ($3::bigint IS NULL AND empresa_id IS NULL)
       OR empresa_id = $3)
  AND (cardinality($4::text[]) = 0 OR estado = ANY($4::text[]))
  AND (cardinality($5::bigint[]) = 0 OR tipo_id = ANY($5::bigint[]))
  AND ($6::bigint IS NULL OR tecnico_id = $6)
  AND (NOT $7::boolean OR tecnico_id IS NULL)
  AND ($8::bigint IS NULL OR ticket_id = $8)
  AND ($9::bigint IS NULL OR cliente_id = $9)
  AND ($10::bigint IS NULL OR servicio_id = $10)
  AND ($11::bigint IS NULL OR zona_id = $11)
  AND ($12::bigint IS NULL OR cuadrilla_id = $12)
  AND ($13::timestamptz IS NULL OR programada_inicio >= $13)
  AND ($14::timestamptz IS NULL OR programada_inicio < $14)
  AND ($15::text IS NULL OR numero ILIKE '%' || $15 || '%' OR direccion ILIKE '%' || $15 || '%'
       OR contacto_nombre ILIKE '%' || $15 || '%')
  AND (CASE WHEN $16::boolean THEN tecnico_id = $17
       ELSE ($18::boolean
             OR zona_id = ANY($19::bigint[])
             OR cuadrilla_id = ANY($20::bigint[])
             OR ($17::bigint IS NOT NULL AND tecnico_id = $17)) END)
ORDER BY id DESC
LIMIT $21
`

type ListarOrdenesParams struct {
	AntesDe       *int64
	TodasEmpresas bool
	EmpresaID     *int64
	Estados       []string
	Tipos         []int64
	TecnicoID     *int64
	SinTecnico    bool
	TicketID      *int64
	ClienteID     *int64
	ServicioID    *int64
	ZonaID        *int64
	CuadrillaID   *int64
	Desde         *time.Time
	Hasta         *time.Time
	Q             *string
	SoloPropias   bool
	ActorID       *int64
	AlcanceGlobal bool
	Zonas         []int64
	Cuadrillas    []int64
	Limite        int32
}

// Más recientes primero (cursor: id). El alcance limita a zonas, cuadrillas o lo asignado al
// actor; solo_propias (ordenes.ver_propias sin ordenes.ver) deja solo las del actor.
